<style>
*{box-sizing:border-box}body{margin:0;background:#edf1f5;color:#000;font:7pt Arial,sans-serif;line-height:1.08}.toolbar{position:sticky;top:0;padding:14px 20px;background:#13283e;color:white;display:flex;gap:12px;align-items:center;flex-wrap:wrap;z-index:2;font:14px Arial,sans-serif}.toolbar a{color:white}.toolbar small{width:100%}button{border:0;border-radius:5px;padding:10px 16px;background:#315acb;color:white;cursor:pointer}.print-sheet{width:215.9mm;min-height:330.2mm;background:white;margin:20px auto;padding:12.7mm;box-shadow:0 1px 8px #0002;break-after:page}.print-sheet:last-child{break-after:auto}.sheet-A{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:6.3mm;align-items:start}.copy{min-width:0}.copy-content{overflow-wrap:anywhere}.copy-id{text-align:right;font-size:6pt;margin-bottom:1mm}h1{text-align:center;font-size:7pt;line-height:1.15;margin:0 0 1.5mm}h2{font-size:7pt;margin:1.6mm 0 .5mm;break-after:avoid}.meta p{margin:.35mm 0}.meta b{font-weight:normal}.meta .value{font-weight:bold}table{border-collapse:collapse;table-layout:fixed;width:100%;margin:.5mm 0}td,th{border:.2mm solid #000;padding:.45mm .7mm;text-align:left;vertical-align:top}thead{display:table-header-group}tr{break-inside:avoid}thead th{text-align:center;background:#e2e8f0}.scale th{background:white}.scale .scale-number{width:10%}.scale .scale-label{width:31%}.scale td:first-child{text-align:center;font-weight:bold}.ratings .benchmark{width:65%}.ratings .verification{width:34%}.ratings.sef .benchmark{width:42%}.rating{text-align:center;vertical-align:middle;padding:.45mm .1mm}.section-heading th{background:#111;color:white;font-weight:normal;padding:.7mm}.section-description td{font-size:6pt;font-style:italic;line-height:1.08}.marked{display:inline-block;border:.3mm solid #000;border-radius:50%;min-width:3.4mm;line-height:3.1mm;text-align:center;font-weight:bold}.answer{white-space:pre-wrap;margin:1mm 0;overflow-wrap:anywhere}.comments{min-height:13mm;border-bottom:.2mm so